#pragma once
// GPL-3.0-only. Effective SOT mapping follows pinned BORIS SOTField;
// xi_A/B and r_A/B are project phenomenological extensions, not transport.
constexpr double SOT_MUB_E=5.788381608e-5;
struct CurrentSOT {V J{},d{},origin_nm{};std::array<double,2>xi{},r{};double raw_limit=1e-8;std::vector<unsigned long>events;};
V sot_cross(V a,V b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}
V sot_field(V m,int i,const UserConfig&u,const CurrentSOT&c){V q=sot_cross(c.d,c.J);if(c.xi[i]==0||dot(q,q)==0)return {};double C=c.xi[i]*SOT_MUB_E/(u.c.Ms[i]*u.c.h[2]);return (sot_cross(m,q)+q*c.r[i])*(-C/u.gamma[i]);}
V sot_rhs(V m,V H,int i,const UserConfig&u,const CurrentSOT&c){V q=sot_cross(c.d,c.J);if(c.xi[i]==0||dot(q,q)==0)return gilbert(m,H,u.gamma[i]/GAMMA_SD,u.alpha[i]);return gilbert(m,H+sot_field(m,i,u,c),u.gamma[i]/GAMMA_SD,u.alpha[i]);}
V sot_only(V m,int i,const UserConfig&u,const CurrentSOT&c){return gilbert(m,sot_field(m,i,u,c),u.gamma[i]/GAMMA_SD,u.alpha[i]);}
CurrentSOT read_sot(const std::filesystem::path&p,const UserConfig&u,unsigned long target){std::ifstream f(p);std::string magic;CurrentSOT c;unsigned long n;f>>magic>>c.J.x>>c.J.y>>c.J.z>>c.d.x>>c.d.y>>c.d.z;take(f,c.xi);take(f,c.r);f>>c.origin_nm.x>>c.origin_nm.y>>c.origin_nm.z>>c.raw_limit>>n;if(!f||magic!="CURRENT-SOT-v1"||!finite(c.J)||c.J.z!=0||!finite(c.d)||std::abs(norm(c.d)-1)>1e-12||!finite(c.origin_nm)||c.raw_limit!=1e-8||n>1000000)throw std::runtime_error("constant current SOT contract");for(int i=0;i<2;i++)if(!std::isfinite(c.xi[i])||!std::isfinite(c.r[i])||!std::isfinite(c.xi[i]*SOT_MUB_E/(u.c.Ms[i]*u.c.h[2])))throw std::runtime_error("SOT finite coefficient");for(unsigned long i=0;i<n;i++){unsigned long k;f>>k;if(k>target||(i&&k<=c.events.back()))throw std::runtime_error("SOT output steps");c.events.push_back(k);}std::string extra;if(!f||f>>extra)throw std::runtime_error("SOT config trailing/truncated");return c;}
Spins current_rhs(const Spins&m,const Evaluation&e,const UserConfig&u,const CurrentSOT&c){Spins out=m;for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++){out[i][j]=sot_rhs(m[i][j],e.H[i][j],i,u,c);if(!finite(out[i][j]))throw std::runtime_error("nonfinite driven RHS");}return out;}
std::array<double,2>current_work(const Spins&m,const Evaluation&e,const UserConfig&u,const CurrentSOT&c){std::array<double,2>p{};for(int i=0;i<2;i++){long double s=0;for(size_t j=0;j<m[i].size();j++)s+=dot(e.H[i][j],sot_only(m[i][j],i,u,c));p[i]=-static_cast<double>(s)*mu0*u.c.Ms[i]*u.c.volume/2;if(!std::isfinite(p[i]))throw std::runtime_error("nonfinite drive work");}return p;}
